365	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
366	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
367	/// always already truncated to local midnight (`EntryDateGroup`'s own
368	/// contract).
369	String _dayLabel(DateTime date) {
370	  final now = DateTime.now();
371	  final today = DateTime(now.year, now.month, now.day);
372	  final yesterday = today.subtract(const Duration(days: 1));
373	  if (date == today) {
374	    return 'Hoje';
375	  }
376	  if (date == yesterday) {
377	    return 'Ontem';
378	  }
379	  final day = date.day.toString().padLeft(2, '0');
380	  final month = date.month.toString().padLeft(2, '0');
381	  return '$day/$month/${date.year}';
382	}
